package org.sleepwell.app;
import java.util.*;
/** Descriptive per-record comparison. No causal attribution, inferred absent days or dose recommendation. */
final class TagImpact {
 static final class Group {final int count;final long mean,median;Group(List<Long> values){count=values.size();List<Long> sorted=new ArrayList<>(values);Collections.sort(sorted);long sum=0;for(long v:sorted)sum=Math.addExact(sum,v);mean=count==0?0:sum/count;median=count==0?0:count%2==1?sorted.get(count/2):(sorted.get(count/2-1)+sorted.get(count/2))/2;}}
 static final class QuantityGroup {final int count;final double minimum,maximum;final Double correlation;QuantityGroup(List<Double> values,List<Double> durations){count=values.size();minimum=Collections.min(values);maximum=Collections.max(values);double x=0,y=0;for(int n=0;n<count;n++){x+=values.get(n);y+=durations.get(n);}x/=count;y/=count;double xx=0,yy=0,xy=0;for(int n=0;n<count;n++){double dx=values.get(n)-x,dy=durations.get(n)-y;xx+=dx*dx;yy+=dy*dy;xy+=dx*dy;}correlation=count<3||xx<=0||yy<=0?null:Math.max(-1,Math.min(1,xy/Math.sqrt(xx*yy)));}}
 final Map<String,QuantityGroup> quantityStats;final Group tagged,other;final int skipped,manual,imported,recorded,quantified;final Map<String,List<Double>> quantities;
 TagImpact(List<RecordEntry> rows,String tag,long now){List<RecordEntry> candidates=new ArrayList<>();int excluded=0;for(RecordEntry row:rows){if(row.edit.end>now||row.edit.end<=row.edit.start||row.edit.tags.stream().anyMatch(t->t.equalsIgnoreCase("nap"))||row.duration()<=0){excluded++;continue;}candidates.add(row);}candidates.sort(Comparator.comparingLong(v->v.edit.start));Set<Long> overlaps=new HashSet<>();long furthest=Long.MIN_VALUE;RecordEntry owner=null;for(RecordEntry row:candidates){if(row.edit.start<furthest){overlaps.add(row.id);if(owner!=null)overlaps.add(owner.id);}if(row.edit.end>furthest){furthest=row.edit.end;owner=row;}}
  List<Long> with=new ArrayList<>(),without=new ArrayList<>();Map<String,List<Double>> values=new TreeMap<>(),durations=new TreeMap<>();int m=0,i=0,measured=0,q=0;for(RecordEntry row:candidates){if(overlaps.contains(row.id)){excluded++;continue;}String found=row.edit.tags.stream().filter(t->t.equalsIgnoreCase(tag)).findFirst().orElse(null);(found==null?without:with).add(row.duration());if(!row.healthConnect.isEmpty())i++;else if(row.manual())m++;else measured++;if(found!=null){TagQuantity quantity=row.edit.quantities.get(found);if(quantity!=null){q++;values.computeIfAbsent(quantity.unit,k->new ArrayList<>()).add(quantity.value);durations.computeIfAbsent(quantity.unit,k->new ArrayList<>()).add((double)row.duration());}}}Map<String,QuantityGroup> associations=new TreeMap<>();values.forEach((unit,v)->associations.put(unit,new QuantityGroup(v,durations.get(unit))));quantityStats=Collections.unmodifiableMap(associations);Map<String,List<Double>> frozen=new TreeMap<>();values.forEach((k,v)->frozen.put(k,List.copyOf(v)));tagged=new Group(with);other=new Group(without);skipped=excluded;manual=m;imported=i;recorded=measured;quantified=q;quantities=Collections.unmodifiableMap(frozen);
 }
 static List<String> names(List<RecordEntry> rows){TreeMap<String,String> names=new TreeMap<>();for(RecordEntry row:rows)for(String tag:row.edit.tags)names.putIfAbsent(tag.toLowerCase(Locale.ROOT),tag);return List.copyOf(names.values());}
}
